-- 00362 — بقع التوقف (Stop hotspots) على الخريطة الحية
-- محرك يستخرج «أحداث التوقف» للآليات المربوطة من السجل الخام gps_device_position_history
-- (اليوم كاملاً، داخل الانطلاقات وخارجها) تراكمياً مع علامة مائية لكل جهاز، ثم يجمّعها بقعاً
-- مرتّبة بإجمالي زمن التوقف لنافذة 24 ساعة / 3 أيام / 7 أيام (الحد الأقصى قابل للضبط)،
-- مع استبعاد زونات/معالم محددة (كراج، محطة، …) وحذف تلقائي للأحداث الأقدم من الحد الأقصى.
-- لا تُخزَّن مسارات يومية — أحداث التوقف فقط (نقطة + مدة).

-- ───────────── الإعدادات ─────────────
create table public.gps_stop_hotspot_settings (
  id smallint primary key default 1 check (id = 1),
  enabled boolean not null default true,
  max_days integer not null default 7 check (max_days between 1 and 30),
  stop_speed_kmh numeric(6,2) not null default 3 check (stop_speed_kmh between 0 and 30),
  stop_min_seconds integer not null default 180 check (stop_min_seconds between 30 and 7200),
  gap_split_seconds integer not null default 900 check (gap_split_seconds between 120 and 21600),
  cluster_radius_m integer not null default 60 check (cluster_radius_m between 20 and 500),
  refresh_minutes integer not null default 30 check (refresh_minutes between 5 and 360),
  landmark_exclude_radius_m integer not null default 150 check (landmark_exclude_radius_m between 20 and 2000),
  excluded_zone_ids uuid[] not null default '{}',
  excluded_landmark_ids uuid[] not null default '{}',
  last_refresh_at timestamptz,
  last_refresh_ms integer,
  updated_by uuid references auth.users(id),
  updated_at timestamptz not null default now()
);
insert into public.gps_stop_hotspot_settings (id) values (1);
alter table public.gps_stop_hotspot_settings enable row level security;
create policy "gps stop settings read" on public.gps_stop_hotspot_settings for select to authenticated
  using (app.has_role(array['ops_room','deputy_director','executive_director','it_admin','super_admin']));

-- ───────────── أحداث التوقف ─────────────
create table public.gps_stop_events (
  id bigint generated by default as identity primary key,
  device_id uuid not null references public.gps_devices(id) on delete cascade,
  garage_vehicle_id uuid references public.garage_vehicles(id) on delete set null,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  duration_seconds integer not null check (duration_seconds >= 0),
  latitude float8 not null check (latitude between -90 and 90),
  longitude float8 not null check (longitude between -180 and 180),
  address text,
  point_count integer not null default 0,
  excluded boolean not null default false,
  excluded_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (device_id, started_at),
  check (ended_at >= started_at)
);
create index gps_stop_events_window_idx on public.gps_stop_events (ended_at desc) where not excluded;
create index gps_stop_events_vehicle_idx on public.gps_stop_events (garage_vehicle_id, ended_at desc);
alter table public.gps_stop_events enable row level security;
create policy "gps stop events read" on public.gps_stop_events for select to authenticated
  using (app.has_role(array['ops_room','deputy_director','executive_director','it_admin','super_admin']));

-- علامة مائية لكل جهاز: من أين يبدأ المسح التالي (بداية التوقف المفتوح أو آخر نقطة)
create table public.gps_stop_scan_state (
  device_id uuid primary key references public.gps_devices(id) on delete cascade,
  scan_from timestamptz,
  last_fix_at timestamptz,
  last_scan_at timestamptz not null default now(),
  last_points integer not null default 0
);
alter table public.gps_stop_scan_state enable row level security;

-- ───────────── الاستبعاد ─────────────
create or replace function app.gps_stop_is_excluded(p_lat float8, p_lng float8)
returns text language plpgsql stable set search_path = public, app as $$
declare s public.gps_stop_hotspot_settings%rowtype; r record;
begin
  select * into s from public.gps_stop_hotspot_settings where id = 1;
  if s.id is null then return null; end if;
  for r in select z.id, z.name, z.polygon from public.gps_geofences z where z.id = any(s.excluded_zone_ids) loop
    if app.gps_point_in_polygon(p_lat, p_lng, r.polygon) then return 'زون: ' || r.name; end if;
  end loop;
  for r in select l.id, l.name from public.gps_map_landmarks l where l.id = any(s.excluded_landmark_ids)
           and app.trip_route_haversine_m(p_lat, p_lng, l.latitude, l.longitude) <= s.landmark_exclude_radius_m loop
    return 'معلم: ' || r.name;
  end loop;
  return null;
end $$;

-- ───────────── مسح جهاز واحد ─────────────
create or replace function app.gps_stop_scan_device(p_device_id uuid, p_from timestamptz, p_to timestamptz)
returns table (upserted integer, points integer, next_scan_from timestamptz, last_fix timestamptz)
language plpgsql volatile set search_path = public, app as $$
declare
  s public.gps_stop_hotspot_settings%rowtype;
  v_vehicle uuid; v_up integer := 0; v_points integer := 0; v_last timestamptz; v_open_start timestamptz;
begin
  select * into s from public.gps_stop_hotspot_settings where id = 1;
  select b.garage_vehicle_id into v_vehicle from public.gps_vehicle_bindings b where b.device_id = p_device_id;
  create temp table if not exists tmp_gps_stop_groups (
    started_at timestamptz, ended_at timestamptz, lat float8, lng float8, address text, point_count integer
  ) on commit drop;
  truncate tmp_gps_stop_groups;
  with p as (
    select h.fix_time, h.latitude lat, h.longitude lng, coalesce(h.speed, 0) spd, nullif(trim(h.address), '') address
    from public.gps_device_position_history h
    where h.device_id = p_device_id and h.fix_time >= p_from and h.fix_time <= p_to
      and h.latitude is not null and h.longitude is not null
      and not (abs(h.latitude) < 0.01 and abs(h.longitude) < 0.01)
  ), q as (
    select p.*, (p.spd <= s.stop_speed_kmh) stopped,
           lag(p.fix_time) over (order by p.fix_time) prev_time,
           lag(p.spd <= s.stop_speed_kmh) over (order by p.fix_time) prev_stopped
    from p
  ), g as (
    select q.*, sum(case when q.stopped and (q.prev_stopped is distinct from true
                               or extract(epoch from q.fix_time - q.prev_time) > s.gap_split_seconds) then 1 else 0 end)
                over (order by q.fix_time) grp
    from q
  )
  insert into tmp_gps_stop_groups (started_at, ended_at, lat, lng, address, point_count)
  select min(fix_time), max(fix_time), avg(lat), avg(lng), mode() within group (order by address), count(*)
  from g where stopped group by grp;
  select count(*) into v_points from public.gps_device_position_history h
   where h.device_id = p_device_id and h.fix_time >= p_from and h.fix_time <= p_to;
  select max(h.fix_time) into v_last from public.gps_device_position_history h
   where h.device_id = p_device_id and h.fix_time >= p_from and h.fix_time <= p_to;
  -- توقف مفتوح: آخر مجموعة تنتهي عند آخر نقطة ⇒ المسح القادم يبدأ من بدايتها كي تتحدّث مدتها
  select t.started_at into v_open_start from tmp_gps_stop_groups t where t.ended_at = v_last order by t.started_at desc limit 1;
  insert into public.gps_stop_events (device_id, garage_vehicle_id, started_at, ended_at, duration_seconds, latitude, longitude, address, point_count, excluded, excluded_reason)
  select p_device_id, v_vehicle, t.started_at, t.ended_at, extract(epoch from t.ended_at - t.started_at)::integer, t.lat, t.lng, t.address, t.point_count,
         x.reason is not null, x.reason
  from tmp_gps_stop_groups t cross join lateral (select app.gps_stop_is_excluded(t.lat, t.lng) reason) x
  where extract(epoch from t.ended_at - t.started_at) >= s.stop_min_seconds
  on conflict (device_id, started_at) do update set
    garage_vehicle_id = excluded.garage_vehicle_id, ended_at = excluded.ended_at, duration_seconds = excluded.duration_seconds,
    latitude = excluded.latitude, longitude = excluded.longitude, address = coalesce(excluded.address, gps_stop_events.address),
    point_count = excluded.point_count, excluded = excluded.excluded, excluded_reason = excluded.excluded_reason, updated_at = now();
  get diagnostics v_up = row_count;
  return query select v_up, v_points, coalesce(v_open_start, v_last), v_last;
end $$;

-- ───────────── التحديث الدوري (كل الأجهزة المربوطة) ─────────────
-- p_budget_ms: سقف زمني للمسح (التشغيل الدوري 120 ث؛ التحديث الكسول من الخريطة 3 ث) — ما لم يُنجز يُستكمل في الدورة التالية.
-- يُمسح كل جهاز على شرائح 24 ساعة كي لا تُحمَّل أيام الإعداد الأول دفعة واحدة.
create or replace function app.gps_stop_hotspots_refresh(p_budget_ms integer default 120000)
returns table (devices integer, upserted integer, purged integer, took_ms integer, caught_up boolean)
language plpgsql volatile security definer set search_path = public, app as $$
declare
  s public.gps_stop_hotspot_settings%rowtype; d record; r record; t0 timestamptz := clock_timestamp();
  v_devices integer := 0; v_up integer := 0; v_purged integer := 0; v_floor timestamptz; v_from timestamptz; v_to timestamptz;
  v_done boolean := true;
begin
  select * into s from public.gps_stop_hotspot_settings where id = 1;
  if not s.enabled then return query select 0, 0, 0, 0, true; return; end if;
  v_floor := now() - make_interval(days => s.max_days);
  for d in select b.device_id, st.scan_from from public.gps_vehicle_bindings b
           left join public.gps_stop_scan_state st on st.device_id = b.device_id
           order by st.last_scan_at nulls first loop
    if extract(epoch from clock_timestamp() - t0) * 1000 > p_budget_ms then v_done := false; exit; end if;
    v_devices := v_devices + 1;
    v_from := greatest(coalesce(d.scan_from, v_floor), v_floor);
    v_to := least(now(), v_from + interval '24 hours');
    loop
      select * into r from app.gps_stop_scan_device(d.device_id, v_from, v_to);
      v_up := v_up + coalesce(r.upserted, 0);
      -- العلامة المائية: بداية التوقف المفتوح أو آخر نقطة؛ وإن خلت الشريحة من نقاط نقفز إلى نهايتها
      v_from := coalesce(r.next_scan_from, v_to);
      insert into public.gps_stop_scan_state (device_id, scan_from, last_fix_at, last_scan_at, last_points)
      values (d.device_id, v_from, r.last_fix, now(), coalesce(r.points, 0))
      on conflict (device_id) do update set scan_from = excluded.scan_from,
        last_fix_at = coalesce(excluded.last_fix_at, gps_stop_scan_state.last_fix_at), last_scan_at = now(), last_points = excluded.last_points;
      exit when v_to >= now();
      -- نهاية الشريحة تتقدم دائماً 24 ساعة (حتى لو بقيت البداية عند توقف مفتوح طويل) ⇒ لا حلقة لا نهائية
      v_to := least(now(), v_to + interval '24 hours');
      if extract(epoch from clock_timestamp() - t0) * 1000 > p_budget_ms then v_done := false; exit; end if;
    end loop;
    exit when not v_done;
  end loop;
  -- إعادة تقييم الاستبعاد (قد تتغير القائمة) ثم حذف ما تجاوز الحد الأقصى
  update public.gps_stop_events e set excluded = x.reason is not null, excluded_reason = x.reason
    from (select e2.id, app.gps_stop_is_excluded(e2.latitude, e2.longitude) reason from public.gps_stop_events e2 where e2.ended_at >= v_floor) x
    where x.id = e.id and (e.excluded <> (x.reason is not null) or e.excluded_reason is distinct from x.reason);
  delete from public.gps_stop_events where ended_at < v_floor;
  get diagnostics v_purged = row_count;
  update public.gps_stop_hotspot_settings set last_refresh_at = now(),
    last_refresh_ms = (extract(epoch from clock_timestamp() - t0) * 1000)::integer where id = 1;
  return query select v_devices, v_up, v_purged, (extract(epoch from clock_timestamp() - t0) * 1000)::integer, v_done;
end $$;
revoke all on function app.gps_stop_hotspots_refresh(integer) from public, anon, authenticated;

-- ───────────── الاستعلام للخريطة ─────────────
create or replace function public.gps_stop_hotspots(p_hours integer default 24)
returns jsonb language plpgsql volatile security definer set search_path = public, app as $$
declare
  s public.gps_stop_hotspot_settings%rowtype; v_hours integer; v_from timestamptz; v_cell_lat float8; v_cell_lng float8;
  v_spots jsonb; v_total jsonb; v_meta jsonb;
begin
  if auth.uid() is null or not app.has_role(array['ops_room','deputy_director','executive_director','it_admin','super_admin']) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into s from public.gps_stop_hotspot_settings where id = 1;
  v_hours := least(greatest(coalesce(p_hours, 24), 1), s.max_days * 24);
  v_from := now() - make_interval(hours => v_hours);
  -- تحديث كسول إن كان الدوري متأخراً (قفل استشاري كي لا يتزاحم مستخدمان)
  if s.enabled and (s.last_refresh_at is null or s.last_refresh_at < now() - make_interval(mins => s.refresh_minutes * 2))
     and pg_try_advisory_xact_lock(hashtext('gps_stop_hotspots_refresh')) then
    perform app.gps_stop_hotspots_refresh(3000);
    select * into s from public.gps_stop_hotspot_settings where id = 1;
  end if;
  v_cell_lat := s.cluster_radius_m / 111320.0;
  v_cell_lng := s.cluster_radius_m / (111320.0 * cos(radians(33.3)));
  -- تجميع شبكي ثم ضمّ كل خلية إلى أثقل خلية مجاورة (3×3) كي لا تنقسم البقعة الواحدة على حدّ شبكة
  with e0 as (
    select e.*, floor(e.latitude / v_cell_lat)::bigint cy0, floor(e.longitude / v_cell_lng)::bigint cx0
    from public.gps_stop_events e where not e.excluded and e.ended_at >= v_from
  ), w as (
    select cy0, cx0, sum(duration_seconds) wsec from e0 group by cy0, cx0
  ), parent as (
    select a.cy0, a.cx0,
           (select b.cy0 from w b where b.cy0 between a.cy0 - 1 and a.cy0 + 1 and b.cx0 between a.cx0 - 1 and a.cx0 + 1 order by b.wsec desc, b.cy0, b.cx0 limit 1) py,
           (select b.cx0 from w b where b.cy0 between a.cy0 - 1 and a.cy0 + 1 and b.cx0 between a.cx0 - 1 and a.cx0 + 1 order by b.wsec desc, b.cy0, b.cx0 limit 1) px
    from w a
  ), e as (
    select e0.*, p.py cy, p.px cx from e0 join parent p on p.cy0 = e0.cy0 and p.cx0 = e0.cx0
  ), c as (
    select cy, cx, count(*) stops, sum(duration_seconds)::bigint total_seconds, max(duration_seconds) max_seconds,
           round(avg(duration_seconds))::integer avg_seconds, count(distinct device_id) vehicles,
           sum(latitude * greatest(duration_seconds, 1)) / sum(greatest(duration_seconds, 1)) lat,
           sum(longitude * greatest(duration_seconds, 1)) / sum(greatest(duration_seconds, 1)) lng,
           max(ended_at) last_at, min(started_at) first_at,
           mode() within group (order by address) address,
           count(*) filter (where ended_at >= now() - interval '24 hours') stops_24h,
           bool_or(ended_at >= now() - interval '15 minutes') active_now,
           mode() within group (order by extract(hour from started_at at time zone 'Asia/Baghdad')::integer) peak_hour
    from e group by cy, cx
  ), ranked as (
    select c.*, row_number() over (order by total_seconds desc, stops desc) rnk,
           max(total_seconds) over () top_seconds
    from c
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.cy || ':' || r.cx, 'rank', r.rnk, 'lat', r.lat, 'lng', r.lng,
      'stops', r.stops, 'stops_24h', r.stops_24h, 'vehicles', r.vehicles,
      'total_seconds', r.total_seconds, 'avg_seconds', r.avg_seconds, 'max_seconds', r.max_seconds,
      'score', round((r.total_seconds::numeric / greatest(r.top_seconds, 1)), 3),
      'level', case when r.total_seconds >= r.top_seconds * 0.66 then 'high' when r.total_seconds >= r.top_seconds * 0.33 then 'medium' else 'low' end,
      'first_at', r.first_at, 'last_at', r.last_at, 'active_now', r.active_now, 'peak_hour', r.peak_hour, 'address', r.address,
      'top_vehicles', (
        select coalesce(jsonb_agg(jsonb_build_object('vehicle_id', t.garage_vehicle_id, 'db_number', t.db_number, 'vehicle_name', t.vehicle_name,
                                                     'stops', t.stops, 'total_seconds', t.secs) order by t.secs desc), '[]'::jsonb)
        from (
          select e2.garage_vehicle_id, v.db_number, coalesce(v.vehicle_name, g.name) vehicle_name, count(*) stops, sum(e2.duration_seconds) secs
          from e e2 join public.gps_devices g on g.id = e2.device_id
          left join public.garage_vehicles v on v.id = e2.garage_vehicle_id
          where e2.cy = r.cy and e2.cx = r.cx group by e2.garage_vehicle_id, v.db_number, v.vehicle_name, g.name
          order by secs desc limit 3
        ) t)
    ) order by r.rnk), '[]'::jsonb)
  into v_spots from ranked r;
  select jsonb_build_object(
      'stops', count(*), 'total_seconds', coalesce(sum(duration_seconds), 0), 'vehicles', count(distinct device_id),
      'excluded', (select count(*) from public.gps_stop_events x where x.excluded and x.ended_at >= v_from))
  into v_total from public.gps_stop_events e where not e.excluded and e.ended_at >= v_from;
  v_meta := jsonb_build_object('hours', v_hours, 'max_days', s.max_days, 'enabled', s.enabled, 'cluster_radius_m', s.cluster_radius_m,
    'last_refresh_at', s.last_refresh_at, 'refresh_minutes', s.refresh_minutes, 'generated_at', now(),
    'excluded_zone_ids', to_jsonb(s.excluded_zone_ids), 'excluded_landmark_ids', to_jsonb(s.excluded_landmark_ids));
  return jsonb_build_object('spots', v_spots, 'totals', v_total, 'meta', v_meta);
end $$;
revoke all on function public.gps_stop_hotspots(integer) from public, anon;
grant execute on function public.gps_stop_hotspots(integer) to authenticated;

-- تفاصيل بقعة: آخر التوقفات داخلها (للنافذة المنبثقة/القائمة)
create or replace function public.gps_stop_hotspot_events(p_lat float8, p_lng float8, p_hours integer default 24, p_limit integer default 30)
returns table (id bigint, vehicle_id uuid, db_number text, vehicle_name text, started_at timestamptz, ended_at timestamptz, duration_seconds integer, address text)
language sql stable security definer set search_path = public, app as $$
  select e.id, e.garage_vehicle_id, v.db_number, coalesce(v.vehicle_name, g.name), e.started_at, e.ended_at, e.duration_seconds, e.address
  from public.gps_stop_events e
  join public.gps_devices g on g.id = e.device_id
  left join public.garage_vehicles v on v.id = e.garage_vehicle_id
  cross join (select * from public.gps_stop_hotspot_settings where id = 1) s
  where auth.uid() is not null and app.has_role(array['ops_room','deputy_director','executive_director','it_admin','super_admin'])
    and not e.excluded and e.ended_at >= now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), s.max_days * 24))
    and app.trip_route_haversine_m(e.latitude, e.longitude, p_lat, p_lng) <= s.cluster_radius_m * 1.5
  order by e.ended_at desc limit least(greatest(coalesce(p_limit, 30), 1), 200)
$$;
revoke all on function public.gps_stop_hotspot_events(float8, float8, integer, integer) from public, anon;
grant execute on function public.gps_stop_hotspot_events(float8, float8, integer, integer) to authenticated;

-- ───────────── الإعدادات: قراءة/حفظ/تحديث الآن ─────────────
create or replace function public.gps_stop_hotspot_settings_get()
returns jsonb language plpgsql stable security definer set search_path = public, app as $$
declare s public.gps_stop_hotspot_settings%rowtype;
begin
  if auth.uid() is null or not app.has_role(array['ops_room','deputy_director','executive_director','it_admin','super_admin']) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into s from public.gps_stop_hotspot_settings where id = 1;
  return to_jsonb(s) - 'updated_by' || jsonb_build_object(
    'excluded_zones', (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'name', z.name) order by z.name), '[]'::jsonb)
                       from public.gps_geofences z where z.id = any(s.excluded_zone_ids)),
    'excluded_landmarks', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'category', l.category) order by l.name), '[]'::jsonb)
                           from public.gps_map_landmarks l where l.id = any(s.excluded_landmark_ids)),
    'events_count', (select count(*) from public.gps_stop_events),
    'can_edit', app.has_role(array['ops_room','it_admin','super_admin']));
end $$;
revoke all on function public.gps_stop_hotspot_settings_get() from public, anon;
grant execute on function public.gps_stop_hotspot_settings_get() to authenticated;

create or replace function public.gps_stop_hotspot_settings_save(p_patch jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public, app as $$
declare s public.gps_stop_hotspot_settings%rowtype; v_zones uuid[]; v_landmarks uuid[];
begin
  if auth.uid() is null or not app.has_role(array['ops_room','it_admin','super_admin']) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into s from public.gps_stop_hotspot_settings where id = 1 for update;
  if p_patch ? 'excluded_zone_ids' then
    select coalesce(array_agg(z.id), '{}') into v_zones from public.gps_geofences z
     where z.id in (select (jsonb_array_elements_text(p_patch->'excluded_zone_ids'))::uuid);
  else v_zones := s.excluded_zone_ids; end if;
  if p_patch ? 'excluded_landmark_ids' then
    select coalesce(array_agg(l.id), '{}') into v_landmarks from public.gps_map_landmarks l
     where l.id in (select (jsonb_array_elements_text(p_patch->'excluded_landmark_ids'))::uuid);
  else v_landmarks := s.excluded_landmark_ids; end if;
  update public.gps_stop_hotspot_settings set
    enabled = coalesce((p_patch->>'enabled')::boolean, enabled),
    max_days = coalesce((p_patch->>'max_days')::integer, max_days),
    stop_speed_kmh = coalesce((p_patch->>'stop_speed_kmh')::numeric, stop_speed_kmh),
    stop_min_seconds = coalesce((p_patch->>'stop_min_seconds')::integer, stop_min_seconds),
    gap_split_seconds = coalesce((p_patch->>'gap_split_seconds')::integer, gap_split_seconds),
    cluster_radius_m = coalesce((p_patch->>'cluster_radius_m')::integer, cluster_radius_m),
    refresh_minutes = coalesce((p_patch->>'refresh_minutes')::integer, refresh_minutes),
    landmark_exclude_radius_m = coalesce((p_patch->>'landmark_exclude_radius_m')::integer, landmark_exclude_radius_m),
    excluded_zone_ids = v_zones, excluded_landmark_ids = v_landmarks,
    updated_by = auth.uid(), updated_at = now()
  where id = 1;
  -- تغيير الحد الأقصى أو الاستبعادات يُطبَّق فوراً (بسقف زمني؛ الباقي يُستكمل دورياً)
  perform app.gps_stop_hotspots_refresh(8000);
  insert into public.audit_logs (table_name, record_id, operation, old_row, new_row, changed_fields, actor_id)
  values ('gps_stop_hotspot_settings', '1', 'UPDATE', to_jsonb(s) - 'updated_by',
          (select to_jsonb(x) - 'updated_by' from public.gps_stop_hotspot_settings x where x.id = 1), p_patch, auth.uid());
  return public.gps_stop_hotspot_settings_get();
end $$;
revoke all on function public.gps_stop_hotspot_settings_save(jsonb) from public, anon;
grant execute on function public.gps_stop_hotspot_settings_save(jsonb) to authenticated;

create or replace function public.gps_stop_hotspots_refresh_now()
returns jsonb language plpgsql volatile security definer set search_path = public, app as $$
declare r record;
begin
  if auth.uid() is null or not app.has_role(array['ops_room','it_admin','super_admin']) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if not pg_try_advisory_xact_lock(hashtext('gps_stop_hotspots_refresh')) then
    return jsonb_build_object('ok', false, 'busy', true);
  end if;
  select * into r from app.gps_stop_hotspots_refresh(20000);
  return jsonb_build_object('ok', true, 'devices', r.devices, 'upserted', r.upserted, 'purged', r.purged, 'took_ms', r.took_ms, 'caught_up', r.caught_up);
end $$;
revoke all on function public.gps_stop_hotspots_refresh_now() from public, anon;
grant execute on function public.gps_stop_hotspots_refresh_now() to authenticated;

-- ───────────── الجدولة ─────────────
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'gps_stop_hotspots_refresh';
    perform cron.schedule('gps_stop_hotspots_refresh', '*/15 * * * *', 'select app.gps_stop_hotspots_refresh(120000)');
  end if;
end $$;

